import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

const SESSION_COOKIE = "marketbook_session";

const protectedRoutes: Record<string, "CLIENT" | "VENDOR"> = {
  "/client": "CLIENT",
  "/vendeur": "VENDOR",
  "/inscription/vendeur/abonnement": "VENDOR",
  "/inscription/vendeur/livres": "VENDOR",
};

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  const matchedRoute = Object.keys(protectedRoutes).find((route) =>
    pathname.startsWith(route)
  );

  if (!matchedRoute) {
    return NextResponse.next();
  }

  const sessionCookie = request.cookies.get(SESSION_COOKIE)?.value;

  if (!sessionCookie) {
    const loginUrl =
      protectedRoutes[matchedRoute] === "VENDOR"
        ? new URL("/connexion/vendeur", request.url)
        : new URL("/connexion/client", request.url);
    loginUrl.searchParams.set("redirect", pathname);
    return NextResponse.redirect(loginUrl);
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/client/:path*", "/vendeur/:path*", "/inscription/vendeur/:path*"],
};
